371	<div class="player" id="player" tabindex="0">
372	    <div class="progress-bar"><div class="progress-fill" id="progressFill"></div></div>
373	    <div class="brand-watermark">
374	        <div class="brand-dot"></div>
375	        <div class="brand-name">EDGE Engineers</div>
376	    </div>
377	    <div id="slidesContainer"></div>
378	    <div class="nav" id="nav"></div>
379	</div>
380	
381	<script>
382	const slides = {slides_data};
383	const schematics = {schematics_data};
384	const SLIDE_DURATION = 5000;
385	let current = 0;
386	let timer = null;
387	let progressInterval = null;
388	
389	function render() {{
390	    const container = document.getElementById('slidesContainer');
391	    const nav = document.getElementById('nav');
392	    container.innerHTML = '';
393	    nav.innerHTML = '';
394	
395	    slides.forEach((slide, i) => {{
396	        const div = document.createElement('div');
397	        div.className = 'slide' + (i === current ? ' active' : '');
398	
399	        const svgData = schematics && schematics[i] && schematics[i].svg;
400	
401	        if (slide.type === 'title') {{
402	            div.className += ' slide-title' + (svgData ? ' has-bg-svg' : '');
403	            div.innerHTML = `
404	                ${{svgData ? `<div class="slide-bg-svg">${{svgData}}</div>` : ''}}
405	                <div class="sector-tag">${{slide.sector || '{html_mod.escape(sector)}'}}</div>
406	                <h1>${{slide.headline}}</h1>
407	                ${{slide.subtitle ? `<div class="subtitle">${{slide.subtitle}}</div>` : ''}}
408	                <div class="tagline-bar"></div>
409	            `;
410	        }} else if (slide.type === 'cta') {{
411	            div.className += ' slide-cta' + (svgData ? ' has-bg-svg' : '');
412	            div.innerHTML = `
413	                ${{svgData ? `<div class="slide-bg-svg">${{svgData}}</div>` : ''}}
414	                <h2>${{slide.headline}}</h2>
415	                <div class="cta-url">${{slide.url || 'www.edgeengineers.net'}}</div>
416	                ${{slide.subtitle ? `<div class="cta-sub">${{slide.subtitle}}</div>` : ''}}
417	            `;
418	        }} else {{
419	            div.className += ' slide-content' + (svgData ? ' has-svg' : '');
420	            const bullets = (slide.bullets || []).map(b => `<li>${{b}}</li>`).join('');
421	            div.innerHTML = `
422	                <div class="slide-text">
423	                    <div class="slide-header">
424	                        <div class="slide-number">${{slide.number || (i + 1)}} / ${{slides.length}}</div>
425	                        <h2>${{slide.headline}}</h2>
426	                    </div>
427	                    ${{bullets ? `<ul class="bullets">${{bullets}}</ul>` : ''}}
428	                </div>
429	                ${{svgData ? `<div class="slide-svg">${{svgData}}</div>` : ''}}
430	            `;
431	        }}
432	
433	        container.appendChild(div);
434	
435	        const dot = document.createElement('button');
436	        dot.className = 'nav-dot' + (i === current ? ' active' : '');
437	        dot.onclick = () => goTo(i);
438	        nav.appendChild(dot);
439	    }});
440	}}
441	
442	function goTo(i) {{
443	    current = i;
444	    render();
445	    resetTimer();
446	}}
447	
448	function next() {{
449	    current = (current + 1) % slides.length;
450	    render();
451	    resetTimer();
452	}}
453	
454	function resetTimer() {{
455	    if (timer) clearInterval(timer);
456	    if (progressInterval) clearInterval(progressInterval);
457	    timer = setInterval(next, SLIDE_DURATION);
458	    updateProgress();
459	}}
460	
461	function updateProgress() {{
462	    const bar = document.getElementById('progressFill');
463	    let start = Date.now();
464	    if (progressInterval) clearInterval(progressInterval);
465	    progressInterval = setInterval(() => {{
466	        const elapsed = Date.now() - start;
467	        const pct = Math.min((elapsed / SLIDE_DURATION) * 100, 100);
468	        bar.style.width = pct + '%';
469	    }}, 50);
470	}}
471	
472	// Keyboard controls
473	document.getElementById('player').onkeydown = (e) => {{
474	    if (e.key === 'ArrowRight') next();
475	    if (e.key === 'ArrowLeft') goTo((current - 1 + slides.length) % slides.length);
476	}};
477	
478	render();
479	resetTimer();
480	</script>
481	</body>
482	</html>"""
483	
484	    output_path = os.path.join(output_dir, "video.html")
485	    with open(output_path, "w", encoding="utf-8") as f:
486	        f.write(html_content)
487	
488	    print(f"  \u2713 Video slideshow: {output_path} ({os.path.getsize(output_path) // 1024}KB)")
489	    return output_path
490	
