492	def generate_slides(topic, sector, post_text):
493	    """Parse the LinkedIn post into structured slide content.
494	    This is the fallback if no slides.json is provided.
495	    """
496	    # Try to extract key points from the post for slide content
497	    paragraphs = [p.strip() for p in post_text.split('\n') if p.strip() and not p.startswith('http') and not p.startswith('#')]
498	
499	    # Check if post has bullets (• or - or numbers)
500	    bullet_items = [p for p in paragraphs if p.startswith('•') or p.startswith('-') or p.startswith('  ')]
501	    content_paragraphs = [p for p in paragraphs if not p.startswith('•') and not p.startswith('-')]
502	
503	    slides = [
504	        {
505	            "type": "title",
506	            "headline": topic,
507	            "subtitle": f"{sector} | EDGE Engineers",
508	            "sector": sector
509	        }
510	    ]
511	
512	    # Problem slide
513	    problem_bullets = []
514	    if len(content_paragraphs) >= 2:
515	        problem_bullets = [content_paragraphs[1][:120]]
516	    if bullet_items:
517	        problem_bullets = bullet_items[:3]
518	    if not problem_bullets:
519	        problem_bullets = [f"Industry challenge in {sector} requiring innovative solutions"]
520	
521	    slides.append({
522	        "type": "content",
523	        "headline": "The Challenge",
524	        "bullets": problem_bullets[:3]
525	    })
526	
527	    # Solution slide
528	    solution_bullets = []
529	    for p in content_paragraphs[2:4] if len(content_paragraphs) > 2 else content_paragraphs[-2:]:
530	        solution_bullets.append(p[:120])
531	    while len(solution_bullets) < 2:
532	        solution_bullets.append(f"EDGE Engineers delivers cutting-edge {sector} solutions")
533	    if len(solution_bullets) > 3:
534	        solution_bullets = solution_bullets[:3]
535	
536	    slides.append({
537	        "type": "content",
538	        "headline": "The EDGE Solution",
539	        "bullets": solution_bullets
540	    })
541	
542	    # CTA slide
543	    slides.append({
544	        "type": "cta",
545	        "headline": "Ready to transform your operations?",
546	        "url": "www.edgeengineers.net",
547	        "subtitle": "ESA Incubatee | MaynoothWorks, Co. Kildare"
548	    })
549	
550	    return slides
551	
552	
553	def main():
554	    import argparse
555	    parser = argparse.ArgumentParser(description="Compose EDGE professional video slideshow")
556	    parser.add_argument("--slides", help="Path to slides.json (LLM-generated slide content)")
557	    parser.add_argument("--schematics", help="Path to schematics.json (Moonshot SVG diagrams)")
558	    parser.add_argument("--output-dir", default="./output", help="Output directory")
559	    parser.add_argument("--topic", required=True, help="Video topic")
560	    parser.add_argument("--sector", required=True, help="Industry sector")
561	    parser.add_argument("--post-text", default="", help="LinkedIn post text (for auto-generating slides)")
562	    parser.add_argument("--background", help="Optional background image path")
563	    args = parser.parse_args()
564	
565	    os.makedirs(args.output_dir, exist_ok=True)
566	
567	    # Load or generate slides
568	    if args.slides and os.path.exists(args.slides):
569	        with open(args.slides) as f:
570	            slides = json.load(f)
571	        print(f"  Loaded {len(slides)} slides from {args.slides}")
572	    else:
573	        slides = generate_slides(args.topic, args.sector, args.post_text)
574	        print(f"  Auto-generated {len(slides)} slides from post text")
575	
576	    # Save slides for reference
577	    slides_path = os.path.join(args.output_dir, "slides.json")
578	    with open(slides_path, "w") as f:
579	        json.dump(slides, f, indent=2)
580	    print(f"  Saved slide data: {slides_path}")
581	
582	    # Load schematics if provided
583	    schematics = None
584	    if args.schematics and os.path.exists(args.schematics):
585	        with open(args.schematics) as f:
586	            schematics = json.load(f)
587	        print(f"  Loaded {len(schematics)} schematics from {args.schematics}")
588	
589	    # Build video
590	    video_path = build_video_html(
591	        args.topic, args.sector, slides,
592	        args.output_dir, args.background, schematics
593	    )
594	
595	    # Result manifest
596	    result = {
597	        "video_path": video_path,
598	        "slide_count": len(slides),
599	        "topic": args.topic,
600	        "sector": args.sector,
601	        "auto_generated": args.slides is None
602	    }
603	
604	    result_path = os.path.join(args.output_dir, "video_result.json")
605	    with open(result_path, "w") as f:
606	        json.dump(result, f, indent=2)
607	
608	    print(f"\n  \u2713 Video slideshow ready")
609	    print(f"  Open: {video_path}")
610	    print(f"  Slides: {len(slides)}")
611	
612	    return 0
613	
614	
615	if __name__ == "__main__":
616	    sys.exit(main())
