#!/usr/bin/env python3
"""
EDGE Smart Video — Professional Video Slideshow
Text-first, branded video slideshow with real content generated by LLM.
No reliance on unreliable AI image APIs.

Usage:
  python3 compose_video.py --slides ./output/slides.json --output-dir ./output

  --slides JSON file with an array of slide objects:
    [
      {"type": "title|content|cta", "headline": "...", "bullets": ["..."], "subtitle": "..."}
    ]
"""

import json
import os
import sys
import html as html_mod


BRAND = {
    "bg": "#f0f4f0",         # Light green-gray background
    "surface": "#ffffff",     # White card surface
    "primary": "#1a7a3a",     # Professional deep green
    "primary_dim": "#145c2d", # Darker green for gradients
    "text": "#1e293b",        # Slate-800 near-black text
    "text_dim": "#64748b",    # Slate-500 medium gray
    "accent": "#d97706",      # Amber-600 accent for CTA contrast
    "font": "'Inter', 'Helvetica Neue', Arial, sans-serif"
}


def build_video_html(topic, sector, slides, output_dir, background_image=None, schematics=None):
    """Create a professional auto-advancing video-style slideshow."""
    slides_data = json.dumps(slides)
    schematics_data = json.dumps(schematics) if schematics else "[]"
    bg_style = ""
